package Time3Hot100;

public class TreeNode {

    int val;
    TreeNode left, right;

    public TreeNode() {
    }

    public TreeNode(int val) {
        this.val = val;
    }

    public TreeNode(int val, TreeNode leftChild, TreeNode rightChild) {
        this.val = val;
        this.left = leftChild;
        this.right = rightChild;
    }
